with probes(pack,offset_n) as (select p::uuid,o from (values ('5522b532-5e50-41f2-99a2-10144bd4e8db'),('548f06be-ccf4-426d-b82b-b424137a4438')) p(p) cross join generate_series(0,561,51) o) select pack,offset_n,coalesce(jsonb_agg(jsonb_build_object('content_item_version_id',s.content_item_version_id,'content_key',s.content_key,'item_type',s.item_type,'required_units',s.required_units,'stimulus_image_path',s.stimulus_image_path))filter(where s.content_item_version_id is not null),'[]'::jsonb)items from probes left join lateral public.select_student_practice_items(pack,3,'00000000-0000-4000-8000-000000000000',null,null,null,51,offset_n)s on true group by pack,offset_n order by pack,offset_n;
